import bus from '//libs/ts/common/bus'

import { Platform } from '../types'

import Kind from './kinds'
import * as v1 from './v1'
import * as v2 from './v2'
export { Kind }

// Probe for v2. 1s is generous: GET_PLATFORM is answered synchronously on the Bridge
// side (no service-worker hop), so this only ever measures a same-process postMessage
// round trip. Kept separate from sendAwaitResp's 5s default, which real calls like
// getPage(deep) need. A v1-only Bridge ignores the v2 probe (it's a non-string object),
// so this reliably times out and falls back to v1.
const v = (async () => {
	try {
		await v2.sendAwaitResp<Platform>(Kind.GET_PLATFORM, undefined, 1000)
		return v2
	} catch {
		return v1
	}
})()

/**
 * Sends a message without waiting for a response.
 */
export async function send(kind: Kind, data?: unknown) {
	(await v).send(kind, data)
}

/**
 * Sends a message and awaits a response within `timeoutMs` milliseconds (default 5000, probably overkill).
 */
export async function sendAwaitResp<U>(kind: Kind, data?: unknown, timeoutMs=5000): Promise<U> {
	return (await v).sendAwaitResp<U>(kind, data, timeoutMs)
}

v.then(v => {
	v.setBridgeReqHandler((kind, data) => bus.emit(kind, data))
})

/*
##################
## v1 messaging ##
##################

SDK -> Bridge messages:
JSON.stringify({ event: <kind>, eventType: <MAGIC_VALUE>, data?: unknown, appId: <window.name>})

Bridge -> SDK messages:
JSON.stringify({ event: <kind>, eventType: <MAGIC_VALUE>, data?: unknown})

##################
## v2 messaging ##
##################

SDK -> Bridge requests:
{ id: number, v: 2, kind: <kind>, magicValue: <MAGIC_VALUE>, data?: unknown, appId: <window.name>, sdkVersion: string }

Bridge -> SDK response:
{ respId: number, v: 2, data?: unknown}

Bridge -> SDK requests:
{ id: number, v: 2, kind: <kind>, magicValue: <MAGIC_VALUE>, data?: unknown}

SDK -> Bridge responses: (I don't think there is any use case for this at the moment)
{ respId: number, v: 2, data?: unknown, sdkVersion: string }

########################
## v1 -> v2 migration ##
########################

Moving to v2 messaging needs to be backwards compatible with v1 (users can be on old Bridge versions):
- SDK needs to be able to send either v1 or v2 messages to Bridge
- SDK needs to handle either v1 or v2 messages from Bridge
- version determined by doing a v2 probe at startup, on probe fail, fallback to v1

Goals:
- ID-stamped messages so that associated replies can be tied back to the original sent message
- Stop JSON.stringifying messages unnecessarily.

- (separate) Use message channels instead of postMessage
  - probably between Bridge and proxy frame, proxy and app could still use postMessage, reason:
    - a page-context-changing (e.g. on navigation) app will need to reestablish message channel
    - might be easier if Bridge and proxy maintain single channel and proxy routes messages from postMessage to channel
    - message channel can be initiated from Bridge to proxy; lessens possibility of tampering/interference, accidental or not
    - trusted message channels will remove the necessity of the MAGIC_VALUE and appId (appId currently used to identify
      sender of message, per-app message channels remove ambiguity)
*/
