/**
 * Minimal synchronous pub/sub event bus, shared as a module-level singleton.
 *
 * Handlers register per string key via `on`, which returns an idempotent
 * unsubscribe function. `emit` dispatches synchronously to a snapshot of the
 * current handler set, so handlers may subscribe or unsubscribe mid-dispatch
 * without affecting the in-flight emit. A throwing handler is caught and
 * logged; remaining handlers still run.
 *
 * Payloads are untyped (`unknown`) — callers narrow. Registering the same
 * function twice for a key is a no-op (Set semantics). Keys with no remaining
 * handlers are pruned, so the bus holds no references after full unsubscribe.
 *
 * @example
 * import bus from './bus'
 * const off = bus.on('session:expired', () => relaunch())
 * bus.emit('session:expired')
 * off()
 *
 * @packageDocumentation
 */

type Handler = (data?: unknown) => void
type Off = () => void

export class Bus {
	handlers = new Map<string, Set<Handler>>()

	emit(key: string, data?: unknown) {
		// Snapshot so handlers may subscribe/unsubscribe mid-dispatch, and so
		// one throwing handler doesn't prevent the rest from running.
		for (const handler of [...this.handlers.get(key) ?? []]) {
			try {
				handler(data)
			} catch (err) {
				console.error(`bus: handler for ${key} threw`, err)
			}
		}
	}

	on(key: string, handler: Handler): Off {
		let set = this.handlers.get(key)
		if (!set) this.handlers.set(key, set = new Set())
		set.add(handler)

		return () => {
			set.delete(handler)
			// Only prune if the map still points at this set. A stale off()
			// called after the key was pruned and re-created would otherwise
			// delete the fresh set, silently unsubscribing its handlers.
			if (set.size === 0 && this.handlers.get(key) === set) this.handlers.delete(key)
		}
	}
}

export default new Bus()
