import { Bus } from '//libs/ts/common/bus'

import version from '../version'

import Kind from './kinds'

const MAGIC_VALUE = 'BRIDGE_EVENT' // used for basic/preliminary filtering of messages
const bus = new Bus()
let bridgeReqHandler: (kind: Kind, data?: unknown) => void
export function setBridgeReqHandler(handler: (kind: Kind, data?: unknown) => void) { bridgeReqHandler = handler }

export type Message = {
	event: Kind
	eventType: typeof MAGIC_VALUE
	appId: string
	data?: unknown
	sdkVersion: string
}

export function send(kind: Kind, data?: unknown) {
	const msg: Message = {
		event: kind,
		eventType: MAGIC_VALUE,
		appId: window.name,
		data,
		sdkVersion: version,
	}
	window.parent.postMessage(JSON.stringify(msg), '*')
}

export function sendAwaitResp<U>(kind: Kind, data?: unknown, timeoutMs=5000): Promise<U> {
	// Set up response listener then send.
	// This is the legacy accept-the-first-matching-message-as-response behavior, but adds a timeout safeguard.
	return new Promise<U>((resolve, reject) => {
		const off = bus.on(kind, (data) => {
			clearTimeout(timer)
			off()
			resolve(data as U)
		})
		const timer = setTimeout(() => {
			off()
			reject(new Error(`timeout waiting for ${kind} response from Bridge`))
		}, timeoutMs)
		send(kind, data)
	})
}

// Incoming messages
window.addEventListener('message', (event: MessageEvent<Message>) => {
	if (typeof event.data !== 'string') return
	let payload: Message
	try {
		payload = JSON.parse(event.data)
	} catch {
		return
	}
	if (payload.eventType !== MAGIC_VALUE) return

	// Bridge-initiated requests
	if (payload.event === Kind.SET_OPEN_ENCOUNTER || payload.event === Kind.SET_PATIENT_INFO) {
		bridgeReqHandler?.(payload.event, payload.data)
		return
	}

	bus.emit(payload.event, payload.data)
})
