import Kind from './kinds'

import version from '../version'

const MAGIC_VALUE = 'BRIDGE_EVENT' // used for basic/preliminary filtering of messages

// ── SDK ─> Bridge request and response ───────────────────────────────────────────────────────────────────────────────
type SDKRequest = {
	v: 2
	magicValue: typeof MAGIC_VALUE

	id: number
	sdkVersion: string
	kind: Kind
	data?: unknown
}

type BridgeResponse = {
	v: 2
	magicValue: typeof MAGIC_VALUE

	respId: number
	data?: unknown
}

// ── Bridge ─> SDK request and response ───────────────────────────────────────────────────────────────────────────────
type BridgeRequest = {
	v: 2
	magicValue: typeof MAGIC_VALUE

	id: number
	kind: Kind
	data?: unknown
}

// In case needed in the future?
// type SDKResponse = {
// 	respId: number
// 	v: 2
// 	data?: unknown
// }

// ── End message types ────────────────────────────────────────────────────────────────────────────────────────────────

let msgId = 0
const awaitingResp = new Map<number, (data?: unknown) => void>()
let bridgeReqHandler: (kind: Kind, data?: unknown) => void
export function setBridgeReqHandler(handler: (kind: Kind, data?: unknown) => void) { bridgeReqHandler = handler }

export function send(kind: Kind, data?: unknown) {
	const msg: SDKRequest = {
		id: msgId++,
		v: 2,
		kind,
		magicValue: MAGIC_VALUE,
		data,
		sdkVersion: version,
	}
	window.parent.postMessage(msg, '*')
}

export function sendAwaitResp<U>(kind: Kind, data?: unknown, timeoutMs=5000): Promise<U> {
	const id = msgId++

	return new Promise((resolve, reject) => {
		const timer = setTimeout(() => {
			awaitingResp.delete(id)
			reject(new Error(`timeout waiting for ${kind} response (v2) from Bridge`))
		}, timeoutMs)
		const cb = (data?: unknown) => {
			clearTimeout(timer)
			awaitingResp.delete(id)
			resolve(data as U)
		}

		awaitingResp.set(id, cb)

		const msg: SDKRequest = {
			id,
			v: 2,
			kind,
			magicValue: MAGIC_VALUE,
			data,
			sdkVersion: version,
		}
		window.parent.postMessage(msg, '*')
	})
}

window.addEventListener('message', (ev: MessageEvent<BridgeRequest | BridgeResponse>) => {
	const msg = ev.data
	if (msg?.v !== 2 || msg?.magicValue !== MAGIC_VALUE) {
		return // not one of our messages
	}

	// Bridge ─> SDK requests
	if ('id' in msg) {
		bridgeReqHandler?.(msg.kind, msg.data)
		return
	}

	// Response to SDK ─> Bridge request
	if ('respId' in msg) {
		awaitingResp.get(msg.respId)?.(msg.data)
		return
	}
})
